// ============================================================
// PARSEO DETERMINISTA DE LA SALIDA DEL AGENTE
// El LLM propone, el Code node dispone. Categorias y prioridades
// vienen de una taxonomia cerrada: nada libre llega al CRM ni a Slack.
// ============================================================
const ctx   = $('Code - Construir Contexto').first().json;
const crudo = $input.first().json.output ?? $input.first().json.text ?? '';

const CATEGORIAS  = ['CONSULTA_PEDIDO','DEVOLUCION','RECLAMO_ENVIO','CONSULTA_PRODUCTO','FACTURACION','OTRO'];
const PRIORIDADES = ['ALTA','MEDIA','BAJA'];
const SLA_HORAS   = { ALTA: 4, MEDIA: 24, BAJA: 72 };
const EMOJI       = { ALTA: ':rotating_light:', MEDIA: ':warning:', BAJA: ':white_check_mark:' };

function parsearJSON(txt) {
  const limpio = String(txt).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(limpio); } catch (e) {}
  const m = limpio.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return null;
}

const parsed = parsearJSON(crudo);
const p = parsed || {};

const categoria = CATEGORIAS.includes(String(p.categoria || '').toUpperCase())
  ? String(p.categoria).toUpperCase()
  : 'OTRO';

let prioridad = PRIORIDADES.includes(String(p.prioridad || '').toUpperCase())
  ? String(p.prioridad).toUpperCase()
  : 'MEDIA';

// Override determinista: un intento de inyeccion SIEMPRE escala a ALTA.
if (ctx.inyeccion_detectada) prioridad = 'ALTA';

// SLA calculado con Luxon en el Code node, nunca por el LLM.
const ahora = DateTime.now().setZone('America/Argentina/Buenos_Aires');
const vence = ahora.plus({ hours: SLA_HORAS[prioridad] });

const asuntoRespuesta = String(p.asunto_respuesta || ('Re: ' + ctx.asunto_original)).slice(0, 150);
const cuerpoRespuesta = String(
  p.cuerpo_respuesta ||
  'Hola,\n\nRecibimos tu consulta y un agente del equipo de soporte la va a revisar a la brevedad.\n\nGracias por escribirnos.\nEquipo de Soporte'
).slice(0, 4000);
const resumenOps = String(p.resumen_para_ops || asuntoRespuesta)
  .replace(/\s+/g, ' ').trim().slice(0, 280);

return [{
  json: Object.assign({}, ctx, {
    parseo_ok:        parsed !== null,
    categoria:        categoria,
    prioridad:        prioridad,
    emoji_prioridad:  EMOJI[prioridad],
    sla_horas:        SLA_HORAS[prioridad],
    vence_en:         vence.toFormat('dd/LL/yyyy HH:mm'),
    vence_iso:        vence.toISO(),
    asunto_respuesta: asuntoRespuesta,
    cuerpo_respuesta: cuerpoRespuesta,
    resumen_para_ops: resumenOps
  })
}];

