// ============================================================
// Arma el prompt del resumidor barato (llama-3.1-8b-instant).
// Todo el estado se calcula aca; el modelo solo redacta 3 campos.
// ============================================================
const d = $('Code - Parsear Salida del Agente').first().json;

const prompt_resumen = [
  'HISTORIAL PREVIO',
  '- asunto_principal: ' + d.memoria_asunto,
  '- puntos_clave: '     + d.memoria_puntos,
  '- accion_requerida: ' + d.memoria_accion,
  '',
  'NUEVA INTERACCION',
  '- Asunto: '     + d.asunto_original,
  '- Categoria: '  + d.categoria,
  '- Prioridad: '  + d.prioridad,
  '- Mensaje del cliente: ' + String(d.cuerpo_seguro).slice(0, 1200),
  '- Borrador de respuesta: ' + String(d.cuerpo_respuesta).slice(0, 600)
].join('\n');

return [{ json: Object.assign({}, d, { prompt_resumen: prompt_resumen }) }];

// ============================================================
// Normaliza el resumen a 3 campos fijos + arma el registro
// idempotente que se escribe en Airtable (upsert por Session_ID).
// ============================================================
const d     = $('Code - Preparar Resumen').first().json;
const crudo = $input.first().json.text ?? $input.first().json.output ?? '';

function parsearJSON(txt) {
  const limpio = String(txt).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(limpio); } catch (e) {}
  const m = limpio.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return null;
}

const r = parsearJSON(crudo) || {};

const ahora = DateTime.now().setZone('America/Argentina/Buenos_Aires');

return [{
  json: {
    session_id:             d.session_id,
    record_id:              d.record_id,
    email_cliente:          d.email_cliente,
    nombre_cliente:         d.nombre_cliente || 'Sin nombre',
    asunto_principal:       String(r.asunto_principal || d.asunto_original).slice(0, 200),
    puntos_clave:           String(r.puntos_clave     || d.resumen_para_ops).slice(0, 1000),
    accion_requerida:       String(r.accion_requerida || 'Revisar borrador en Gmail y aprobar envio.').slice(0, 500),
    contador_interacciones: d.contador_interacciones,
    categoria:              d.categoria,
    prioridad:              d.prioridad,
    vence_en:               d.vence_en,
    ultima_actualizacion:   ahora.toISO()
  }
}];
